import java.io.*;
import java.util.*;

public class Main {

    static class Point {
        long[] coords;

        Point(long... coords) {
            this.coords = coords;
        }

        long computeLengthSq() {
            long total = 0;
            for (long c : coords) {
                total += c * c;
            }
            return total;
        }

        long scalarProduct(Point other) {
            long sum = 0;
            for (int i = 0; i < coords.length; i++) {
                sum += coords[i] * other.coords[i];
            }
            return sum;
        }

        Point subtract(Point other) {
            long[] newCoords = new long[coords.length];
            for (int i = 0; i < coords.length; i++) {
                newCoords[i] = coords[i] - other.coords[i];
            }
            return new Point(newCoords);
        }
    }

    public static boolean verify(List<Point> pts, int index) {
        Point current = pts.get(index);
        int totalPoints = pts.size();
        for (int j = 0; j < totalPoints; j++) {
            if (j == index) continue;
            for (int k = 0; k < totalPoints; k++) {
                if (k == index || k == j) continue;
                Point vec1 = pts.get(j).subtract(current);
                Point vec2 = pts.get(k).subtract(current);
                if (vec1.scalarProduct(vec2) > 0) return false;
            }
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());
        if (n > 11) {
            System.out.println(0);
            return;
        }
        List<Point> points = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String[] parts = br.readLine().split(" ");
            long[] coords = new long[5];
            for (int j = 0; j < 5; j++) {
                coords[j] = Long.parseLong(parts[j]);
            }
            points.add(new Point(coords));
        }
        List<Integer> validIndices = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (verify(points, i)) {
                validIndices.add(i + 1);
            }
        }
        System.out.println(validIndices.size());
        for (int idx : validIndices) {
            System.out.println(idx);
        }
    }
}
